#include <algorithm>
#include <array>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>
using namespace std;using R=vector<int>;using ll=long long;using P=array<ll,8>;
void need(bool b,const char*s){if(!b)throw runtime_error(s);}int bit(unsigned b){return __builtin_ctz(b);}R tournament(int n,int code){R r(n);int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){int a=i,b=j;if(!(code>>k++&1))swap(a,b);r[a]|=1<<b;}return r;}R induced(R const&r,vector<int>const&v){R q(v.size());for(int i=0;i<(int)v.size();i++)for(int j=0;j<(int)v.size();j++)if(r[v[i]]>>v[j]&1)q[i]|=1<<j;return q;}R rev(R r){int n=r.size(),F=(1<<n)-1;for(int i=0;i<n;i++)r[i]=F^r[i]^(1<<i);return r;}
struct Inv{ll h;vector<ll>s,e;};Inv literal(R const&r){int n=r.size();Inv z{0,vector<ll>(n),vector<ll>(n)};if(!n){z.h=1;return z;}vector<int>v(n);iota(v.begin(),v.end(),0);do{bool ok=true;for(int i=1;i<n;i++)ok&=r[v[i-1]]>>v[i]&1;if(ok){z.h++;z.s[v[0]]++;z.e[v.back()]++;}}while(next_permutation(v.begin(),v.end()));return z;}
P runs(R const&r,int root){vector<int>v;for(int i=0;i<(int)r.size();i++)if(i!=root)v.push_back(i);P ans{};if(v.empty()){ans[0]=ans[1]=1;return ans;}do{P p{};p[0]=1;auto factor=[&](int a,int b){P q{};for(int k=0;k<8;k++){q[k]+=a*p[k];if(k)q[k]+=b*p[k-1];}p=q;};factor(1,r[root]>>v[0]&1);for(int i=1;i<(int)v.size();i++)factor(r[v[i-1]]>>v[i]&1,(r[v[i-1]]>>root&1)&&(r[root]>>v[i]&1));factor(1,r[v.back()]>>root&1);for(int k=0;k<8;k++)ans[k]+=p[k];}while(next_permutation(v.begin(),v.end()));return ans;}
vector<int>centers(R const&r,int root){vector<pair<int,int>>e;for(int a=0;a<(int)r.size();a++)if(r[root]>>a&1)for(int b=0;b<(int)r.size();b++)if((r[b]>>root&1)&&(r[a]>>b&1))e.emplace_back(a,b);if(e.empty())return{};vector<int>c;for(int v=0;v<(int)r.size();v++)if(all_of(e.begin(),e.end(),[&](auto p){return p.first==v||p.second==v;}))c.push_back(v);return c;}
vector<int>twins(R const&r,int root){vector<int>v;for(int a=0;a<(int)r.size();a++)if(a!=root){bool ok=true;for(int b=0;b<(int)r.size();b++)if(b!=a&&b!=root)ok&=((r[a]>>b&1)==(r[root]>>b&1));if(ok)v.push_back(a);}return v;}
vector<int>scc(R const&r,vector<int>const&vs,bool source){int n=r.size();vector<unsigned>reach(n);for(int a:vs){reach[a]=1<<a;for(int b:vs)if(r[a]>>b&1)reach[a]|=1<<b;}for(int z:vs)for(int a:vs)if(reach[a]>>z&1)reach[a]|=reach[z];for(int a:vs){vector<int>C;for(int b:vs)if((reach[a]>>b&1)&&(reach[b]>>a&1))C.push_back(b);bool good=true;for(int u:C)for(int b:vs)if(find(C.begin(),C.end(),b)==C.end())good&=source?(r[u]>>b&1):(r[b]>>u&1);if(good)return C;}throw runtime_error("SCC not found");}
ll bins2(R const&r){int n=r.size();ll ans=0;for(int mask=0;mask<(1<<n);mask++){vector<int>a,b;for(int i=0;i<n;i++)(mask>>i&1?a:b).push_back(i);ans+=literal(induced(r,a)).h*literal(induced(r,b)).h;}return ans;}
R births(R const&s,int E,int count){int n=s.size();R t=s;t.resize(n+count);for(int j=0;j<count;j++){for(int i=0;i<n;i++)if(E>>i&1)t[n+j]|=1<<i;else t[i]|=1<<(n+j);for(int k=0;k<j;k++)t[n+k]|=1<<(n+j);}return t;}
R replace(R const&s,int root,int count){vector<pair<int,int>>v;for(int i=0;i<(int)s.size();i++)if(i==root){for(int k=0;k<count;k++)v.emplace_back(i,k);}else v.emplace_back(i,0);R t(v.size());for(int i=0;i<(int)v.size();i++)for(int j=i+1;j<(int)v.size();j++){bool ij=v[i].first==v[j].first?v[i].second<v[j].second:(s[v[i].first]>>v[j].first&1);t[ij?i:j]|=1<<(ij?j:i);}return t;}
int main(){ll graphs=0,roots=0,coverchecks=0,zeros=0,units=0,nontwin=0,retractions=0,blocks=0,masks=0,arcchecks=0;for(int n=1;n<=6;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){R T=tournament(n,code);graphs++;ll ht=literal(T).h;for(int root=0;root<n;root++){auto cs=centers(T,root);if(cs.empty())continue;roots++;P a=runs(T,root);need(a[1]==ht&&a[2]>0,"run physical scalar");for(int k=3;k<8;k++)need(!a[k],"rank-one cutoff");ll beta=a[1]-2*a[2],boundary=a[0]-a[1]+a[2];auto tw=twins(T,root);if(!tw.empty())need(boundary==0,"twin converse");if(abs(beta)==1)need((boundary==0)==!tw.empty(),"unit zero iff twin");for(int c:cs){R U=(T[root]>>c&1)?T:rev(T);vector<int>O,I;for(int v=0;v<n;v++)if(v!=root)(U[root]>>v&1?O:I).push_back(v);Inv io=literal(induced(U,O)),ii=literal(induced(U,I));ll s=io.s[find(O.begin(),O.end(),c)-O.begin()],e=0;for(int j=0;j<(int)I.size();j++)if(U[c]>>I[j]&1)e+=ii.e[j];need(boundary==-s*e,"literal endpoint product");coverchecks++;if(boundary)continue;auto C=s==0?scc(U,O,true):scc(U,I,false);need(find(C.begin(),C.end(),c)==C.end(),"center survives");vector<int>V;for(int v=0;v<n;v++)if(find(C.begin(),C.end(),v)==C.end())V.push_back(v);for(int v:C)for(int w:V)if(w!=root)need((U[v]>>w&1)==(U[root]>>w&1),"homogeneous block");int rr=find(V.begin(),V.end(),root)-V.begin();R Q=induced(U,V),S=induced(U,C);P b=runs(Q,rr);ll hc=literal(S).h;need(!centers(Q,rr).empty(),"quotient remains rank one");need(beta==(b[1]-2*b[2])*hc&&a[2]==b[2]*bins2(S),"exact amplitude and offset factorization");if(abs(beta)==1)need(C.size()==1,"unit strong block singleton");blocks++;}
if(!boundary){zeros++;units+=abs(beta)==1;nontwin+=tw.empty();}for(int v:tw){vector<int>V;for(int i=0;i<n;i++)if(i!=v)V.push_back(i);int rr=find(V.begin(),V.end(),root)-V.begin();P b=runs(induced(T,V),rr);need(a[2]==2*b[2]&&beta==b[1]-2*b[2],"exact twin retraction");retractions++;}
if(root==n-1&&!boundary&&abs(beta)==1){masks++;vector<int>V(n-1);iota(V.begin(),V.end(),0);R S=induced(T,V);int w=tw[0],E=T[root]&((1<<root)-1);for(int t=0;t<=3;t++){R born=births(S,E,t),cloned=replace(S,w,t+1);vector<int>map(n-1+t);int pos=0;for(int v=0;v<n-1;v++)if(v!=w)map[v]=pos++;else{if(E>>w&1){for(int j=0;j<t;j++)map[n-1+j]=pos++;map[w]=pos++;}else{map[w]=pos++;for(int j=0;j<t;j++)map[n-1+j]=pos++;}}for(int i=0;i<(int)born.size();i++)for(int j=0;j<(int)born.size();j++){need((born[i]>>j&1)==(cloned[map[i]]>>map[j]&1),"fixed-mask actual old-root clones");arcchecks++;}}}
}}
R hostile{2,32,11,19,7,29};P z=runs(hostile,0);need(z[0]==15&&z[1]==27&&z[2]==12&&twins(hostile,0).empty(),"nonunit hostile");cout<<"{\"status\":\"PASS\",\"labelled_graphs\":"<<graphs<<",\"rank1_roots\":"<<roots<<",\"cover_endpoint_checks\":"<<coverchecks<<",\"zero_boundary_roots\":"<<zeros<<",\"unit_zero_roots\":"<<units<<",\"zero_nontwin_roots\":"<<nontwin<<",\"homogeneous_block_checks\":"<<blocks<<",\"literal_twin_retractions\":"<<retractions<<",\"fixed_mask_unit_seeds\":"<<masks<<",\"fixed_mask_arc_checks\":"<<arcchecks<<"}\n";}
